/** The loan product family classifies a GROUP, never a specific contract such as Mudaraba. */
public static int groupForProductFamily(String familyCode) {
    String family = familyCode == null ? "" : familyCode.trim().toUpperCase(java.util.Locale.ROOT);
    return Arrays.stream(LoanGroup.values())
            .filter(group -> group.productFamilyCode().equals(family))
            .mapToInt(LoanGroup::code).findFirst().orElse(0);
}

/** RETAIL_LOAN is historical and remains readable, but is not offered for new loan products. */
public static boolean isLegacyRetailFamily(String familyCode) {
    return "RETAIL_LOAN".equals(familyCode == null ? "" : familyCode.trim().toUpperCase(java.util.Locale.ROOT));
}

