onLoanApplicantAllChange(checked: boolean): void {
  this.loanApplicantAll.setValue(checked, {emitEvent: false});
  const nature = this.form.controls['PARTY_NATURE_CODE'];
  if (!nature) return;
  if (checked) {
    nature.setValue('ALL', {emitEvent: false});
    nature.disable({emitEvent: false});
  } else {
    nature.setValue(null, {emitEvent: false});
    nature.enable({emitEvent: false});
  }
  nature.updateValueAndValidity({emitEvent: false});
}

private syncLoanApplicantNature(): void {
  if (this.tableName() !== 'LOAN_PRODUCT_PROFILE') return;
  const nature = this.form.controls['PARTY_NATURE_CODE'];
  if (!nature) return;
  const all = String(nature.value ?? '') === 'ALL';
  this.loanApplicantAll.setValue(all, {emitEvent: false});
  if (all) nature.disable({emitEvent: false});
  else nature.enable({emitEvent: false});
}

/** Display only; persistence remains in the required PDL.LOAN_PRODUCT_PROFILE currency column. */
private async loadLoanProductCurrency(): Promise<void> {
  if (this.tableName() !== 'LOAN_PRODUCT_PROFILE') return;
  const version = Number(this.form.controls['PRODUCT_VERSION_ID']?.value);
  this.loanProductCurrency.set(null);
  this.loanAllowedTypeIds.set(null);
  this.loanCurrencyIssue.set(null);
  if (!Number.isSafeInteger(version) || version <= 0) {
    this.loanCurrencyIssue.set('برای تشخیص ارز، ابتدا نسخه محصول تسهیلات باید مشخص باشد.');
    return;
  }
  try {
    const versionRow = await this.service.row('PRODUCT_VERSION', version);
    const productRow = await this.service.row('PRODUCT', Number(versionRow['PRODUCT_ID']));
    const currency = String(productRow['DEFAULT_CURRENCY_CODE'] ?? '').trim().toUpperCase();
    const family = String(productRow['PRODUCT_FAMILY_CODE'] ?? '').trim().toUpperCase();
    if (productRow['PRODUCT_CLASS_CODE'] !== 'LOAN' || !/^[A-Z]{3}$/.test(currency)) {
      this.loanCurrencyIssue.set('دامنه یا ارز پیش‌فرض محصول معتبر نیست؛ به هویت محصول مراجعه کنید.');
      return;
    }
    const match = Object.entries({
      QARD_HASAN_LOAN:1, EXCHANGE_LOAN:2, PARTICIPATORY_LOAN:3, COMMITMENT_LOAN:4
    }).find(([code]) => code === family);
    const group = match ? match[1] : family === 'RETAIL_LOAN' ? null : undefined;
    if (group === undefined) {
      this.loanCurrencyIssue.set('خانواده تسهیلات با طبقه‌بندی عقود سازگار نیست؛ ابتدا هویت محصول را اصلاح کنید.');
      return;
    }
    const loanTypes = new Set<number>();
    let received = 0;
    for (let page = 0; page < 50; page++) {
      const result = await this.service.rows('LOAN_TYPE', {
        page, size:200, ...(group === null ? {} : {filterColumn:'LOAN_GROUP',filterValue:group})
      });
      for (const row of result.items) {
        if (String(row['RECORD_STATUS_CODE']).trim().toUpperCase() === 'ACTIVE') {
          const id = Number(row['LOAN_TYPE_ID']);
          if (Number.isSafeInteger(id) && id > 0) loanTypes.add(id);
        }
      }
      received += result.items.length;
      if (received >= result.totalElements) break;
      if (!result.items.length || page === 49) throw new Error('فهرست انواع عقود ناقص است؛ ثبت پروفایل تا بازیابی کامل متوقف شد.');
    }
    if (Number(this.form.controls['PRODUCT_VERSION_ID']?.value) !== version || this.tableName() !== 'LOAN_PRODUCT_PROFILE') return;
    this.loanAllowedTypeIds.set([...loanTypes]);
    this.loanProductCurrency.set(currency);
    const currentTypeId = Number(this.form.controls['LOAN_TYPE_ID']?.value);
    if (currentTypeId > 0 && !loanTypes.has(currentTypeId)) {
      this.loanCurrencyIssue.set('نوع عقد انتخابی جزو عقود فعال گروه این محصول نیست؛ ابتدا عقد را اصلاح کنید.');
      return;
    }
    const existing = this.editingRow()?.['CURRENCY_TYPE_CODE'];
    if (existing != null && String(existing).trim().toUpperCase() !== currency) {
      this.loanCurrencyIssue.set('ارز پروفایل موجود با ارز اصلی محصول مغایرت دارد؛ این مغایرت نباید به صورت خودکار اصلاح شود.');
      return;
    }
    this.form.controls['CURRENCY_TYPE_CODE']?.setValue(currency, {emitEvent: false});
  } catch (e) {
    this.loanCurrencyIssue.set('خواندن ارز پیش‌فرض از هویت محصول موفق نبود: ' + this.message(e));
  }
}

