private async loadLoanFamilyOptions(): Promise<void> {
  this.loanFamilyLoading.set(true);
  this.loanFamilyLoadError.set(null);
  try {
    const groups = new Set<number>();
    let received = 0;
    for (let page = 0; page < 50; page++) {
      const result = await this.service.rows('LOAN_TYPE', {page, size: 200});
      for (const row of result.items) {
        if (String(row['RECORD_STATUS_CODE']).trim().toUpperCase() === 'ACTIVE') {
          const group = Number(row['LOAN_GROUP']);
          if (Number.isInteger(group) && LOAN_FAMILY_FROM_GROUP[group]) groups.add(group);
        }
      }
      received += result.items.length;
      if (received >= result.totalElements) {
        this.loanFamilyOptions.set([...groups].sort((a,b) => a-b).map(group => LOAN_FAMILY_FROM_GROUP[group]));
        return;
      }
      if (!result.items.length) break;
    }
    throw new Error('فهرست انواع عقود کامل بارگذاری نشد؛ از ثبت خانواده بر اساس داده ناقص جلوگیری شد.');
  } catch (e) {
    this.loanFamilyOptions.set([]);
    this.loanFamilyLoadError.set(this.message(e));
  } finally {
    this.loanFamilyLoading.set(false);
  }
}

